package com.interview.mysqlescdc.verifier.rebuild;
import java.util.concurrent.atomic.AtomicReference;import org.springframework.beans.factory.annotation.Value;import org.springframework.stereotype.Component;
@Component public final class RebuildFailpointRegistry{private final boolean enabled;private final AtomicReference<RebuildFailpoint> value=new AtomicReference<>(RebuildFailpoint.NONE);public RebuildFailpointRegistry(@Value("${lab.failpoints.enabled:false}")boolean enabled){this.enabled=enabled;}public RebuildFailpoint get(){return value.get();}public void set(RebuildFailpoint next){if(!enabled)throw new IllegalStateException("lab failpoints disabled");value.set(next);}public void clear(){value.set(RebuildFailpoint.NONE);}public void check(RebuildFailpoint point){if(value.get()==point)throw new IllegalStateException("rebuild failpoint "+point);}}
